import random, string

class RobotImmediateDiscard:
    _used = set()
    def __init__(self):
        self._name = None
    @property
    def name(self):
        if self._name is None:
            while True:
                cand = random.choice(string.ascii_uppercase) + random.choice(string.ascii_uppercase) + f'{random.randint(0, 999):03d}'
                if cand not in RobotImmediateDiscard._used:
                    RobotImmediateDiscard._used.add(cand)
                    self._name = cand
                    break
        return self._name
    def reset(self):
        if self._name is not None:
            RobotImmediateDiscard._used.discard(self._name)
            self._name = None

random.seed(42)
r = RobotImmediateDiscard()
n1 = r.name
print('n1:', n1)
random.seed(42)
r.reset()
n2 = r.name
print('n2:', n2)
print('Are they equal?', n1 == n2)
"

