import time, random, string

class RobotWhileTrue:
    _used = set()
    _NAME_COUNT = 26 * 26 * 1000

    @classmethod
    def _allocate(cls):
        if len(cls._used) >= cls._NAME_COUNT:
            raise RuntimeError('namespace exhausted')
        while True:
            cand = (
                random.choice(string.ascii_uppercase)
                + random.choice(string.ascii_uppercase)
                + f'{random.randint(0, 999):03d}'
            )
            if cand not in cls._used:
                cls._used.add(cand)
                return cand

t0 = time.time()
try:
    for i in range(676000):
        RobotWhileTrue._allocate()
        if (i + 1) % 100000 == 0:
            print(f'{i+1} allocated in {time.time()-t0:.2f}s...')
except Exception as e:
    print('Failed:', e)
t1 = time.time()
print(f'Total time: {t1-t0:.2f}s, total used: {len(RobotWhileTrue._used)}')
"
